import{_ as e,d,e as o,x as r}from"./chunks/framework.BRr8VP3a.js";const m=JSON.parse('{"title":"Appendix B Numbering Scheme and Glossary","description":"","frontmatter":{"title":"Appendix B Numbering Scheme and Glossary","xkChars":0,"xkWords":485},"headers":[],"relativePath":"en/theory/appendix-b.md","filePath":"en/theory/appendix-b.md"}'),a={name:"en/theory/appendix-b.md"};function i(n,t,c,s,l,p){return d(),o("div",null,[...t[0]||(t[0]=[r('<div class="theory-source"><p><a id="part_18"></a></p><h1 id="part-title-18" tabindex="-1">Appendix B Numbering Scheme and Glossary <a class="header-anchor" href="#part-title-18" aria-label="Permalink to &quot;Appendix B Numbering Scheme and Glossary {#part-title-18}&quot;">​</a></h1><p>The book uses the numbering schemes below. This table serves only as a navigation index. The relevant parts of the main text govern each scheme’s definitions, contracts, and limits on use.</p><div class="xk-table"><table><thead><tr><th>Prefix</th><th>Meaning</th><th>Count</th><th>Where Defined</th></tr></thead><tbody><tr><td><code>D0-D3</code></td><td>Definition layer covering structural objects, basic state terms, effective feedback, and scale transformation</td><td>4</td><td>Part 3</td></tr><tr><td><code>U01-U11</code></td><td>Universal structural primitives</td><td>11</td><td>Part 3</td></tr><tr><td><code>G1-G4</code></td><td>Empirical question families (specific tests are established through a G-instance)</td><td>4</td><td>Part 4</td></tr><tr><td><code>CMC1–CMC3</code></td><td>Common method constraints covering task and representation, evidential status of materials and scope of support, and facts, values, and eligibility to act</td><td>3</td><td>Part 4 and Appendix C</td></tr><tr><td><code>F1-F6</code></td><td>Conditional formal propositions on task recovery, closure, availability of a common feasible action, preservation under composition, error propagation, and refinement of task families</td><td>6</td><td>Part 4 and Appendix C</td></tr><tr><td><code>E1-E5</code></td><td>Epistemic constraints</td><td>5</td><td>Part 4</td></tr><tr><td><code>C1-C12</code></td><td>Outcome contracts, propositions about mechanisms, and procedural bridges</td><td>12</td><td>Part 4</td></tr><tr><td><code>A/X/T/O/C/R/I/N/J</code></td><td>The nine axes of the scale profile SP</td><td>9</td><td>Part 5</td></tr><tr><td><code>M01-M09</code></td><td>Scale transformation operators</td><td>9</td><td>Part 5</td></tr><tr><td><code>CM-*</code></td><td>Conditional mechanisms (<code>FEEDBACK</code>, <code>LEARNING</code>, <code>MAINTENANCE</code>, <code>LOAD</code>, <code>PHASE</code>, and <code>SELECTION</code>)</td><td>6</td><td>Part 6</td></tr><tr><td><code>H1-H6</code></td><td>Human-domain clauses</td><td>6</td><td>Part 7</td></tr><tr><td><code>GC/GS/GE/CV/RS/IS/IM/IB</code></td><td>Three sets of strong types that must be kept distinct (generative condition, generative subject, and generative event, uptake carrier and responsible party, and source/mechanism/behavior of destabilization)</td><td>8</td><td>Part 7</td></tr><tr><td><code>HV01-HV11</code></td><td>Unified interfaces for human variables (see Appendix A for the full interface cards)</td><td>11</td><td>Part 7</td></tr><tr><td><code>S0-S6</code>, <code>X0</code></td><td>Human state prototypes and the orderly exit path</td><td>7+1</td><td>Part 8</td></tr><tr><td><code>IG1-IG7</code></td><td>The seven gates, the only main workflow</td><td>7</td><td>Part 13</td></tr><tr><td><code>SJ1-SJ8</code></td><td>Strong-judgment kit</td><td>8</td><td>Part 13</td></tr><tr><td><code>L1-L3</code></td><td>Diagnostic levels</td><td>3</td><td>Part 13</td></tr><tr><td><code>TOOL-*</code></td><td>Six formal tools (<code>EVIDENCE-LEDGER</code>, <code>OPEN-ASSERTION</code>, <code>CLAIM-VALIDATION</code>, <code>FORECAST-REGISTRY</code>, <code>STRESS-TEST</code>, and <code>AI-BOUNDARY</code>)</td><td>6</td><td>Part 13</td></tr><tr><td><code>N1-N5</code></td><td>Runtime registration of premises for normative choice</td><td>5</td><td>Part 14</td></tr><tr><td><code>O1-O4</code></td><td>Procedures for bounded authorization</td><td>4</td><td>Part 14</td></tr><tr><td><code>PF-1-PF-10</code></td><td>Interface between normative choice and the choice record</td><td>10</td><td>Part 14</td></tr><tr><td><code>T0-T4</code></td><td>Intervention levels</td><td>5</td><td>Part 15</td></tr><tr><td><code>APP-*</code></td><td>Application modules (<code>REL</code>, <code>FAM</code>, <code>ORG</code>, <code>PLT</code>, <code>INS</code>, <code>OPI</code>, <code>SPC</code>, <code>EMG</code>, and <code>ULS</code>)</td><td>9</td><td>Part 15</td></tr><tr><td><code>GOV-01-GOV-24</code></td><td>Governance clauses</td><td>24</td><td>Part 16</td></tr></tbody></table></div><p>Several other symbols recur throughout the book. <code>S*=&lt;B,X,R,I,T,SP,K&gt;</code> gives the seven fields of a D0 candidate object contract (boundary, state variables, relations or transition constraints, interface, time window, scale profile, and identity criterion). <code>N0</code> is the null model. <code>K*/F*</code> are the target identity criterion and the target functional criterion for repair, respectively. <code>G-instance</code> and <code>H-instance</code> denote specific test instances for empirical question families and human-domain clauses, respectively. The first definition of each in the main text governs its use.</p><p>F1–F6 are identifiers for formal propositions. Used on their own, F and F* can denote a dynamic update, a functional criterion, or a repair target according to their local definitions. Use of the same letter does not establish that the object is the same. G3 tests only historical conditional increments beyond the given current representation. When mediated by a carrier, learning, accumulation, sustained effects, and intertemporal reproduction are tested under their respective mechanism contracts. They do not all require positive support from G3.</p></div>',1)])])}const f=e(a,[["render",i]]);export{m as __pageData,f as default};
